--
-- Table structure for table `md_subject`
--

DROP TABLE IF EXISTS `md_subject`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_subject` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `company_id` bigint DEFAULT NULL COMMENT '所属公司ID,空表示租户级共用科目表',
  `subject_code` varchar(64) NOT NULL COMMENT '科目编码,如 660201',
  `subject_name` varchar(200) NOT NULL COMMENT '科目名称',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '上级科目ID',
  `subject_level` int NOT NULL DEFAULT '1' COMMENT '科目级次',
  `subject_type` varchar(20) NOT NULL DEFAULT 'COST' COMMENT '科目类别:ASSET资产/LIABILITY负债/EQUITY权益/COST成本费用/PROFIT损益',
  `direction` varchar(10) NOT NULL DEFAULT 'DEBIT' COMMENT '余额方向:DEBIT借/CREDIT贷',
  `is_leaf` tinyint NOT NULL DEFAULT '1' COMMENT '是否明细科目:0否 1是(仅明细科目可记账)',
  `aux_items` varchar(200) DEFAULT NULL COMMENT '辅助核算项,逗号分隔:DEPT部门/PROJECT项目/SUPPLIER供应商/EMPLOYEE员工',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_subject` (`tenant_id`,`company_id`,`subject_code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_parent` (`tenant_id`,`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=900100301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会计科目';
/*!40101 SET character_set_client = @saved_cs_client */;

